        g.gain.setValueAtTime(isAkzent ? 1.0 : 0.7, t);
        g.gain.exponentialRampToValueAtTime(0.0001, t + 0.4);
        o.connect(g); g.connect(master); o.start(t); o.stop(t + 0.42);
